import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"Netem 故障","description":"","frontmatter":{},"headers":[],"relativePath":"zh/netem-faults.md","filePath":"zh/netem-faults.md"}`),a={name:`zh/netem-faults.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="netem-故障" tabindex="-1">Netem 故障 <a class="header-anchor" href="#netem-故障" aria-label="Permalink to “Netem 故障”">​</a></h1><p>故障模型在 <code>faultdeck-core</code>(<code>FaultSpec</code>);<code>tc netem</code> 适配器在 <code>faultdeck-netem</code>;disconnect 路径在 <code>faultdeck-agent::firewall</code>。以下内容直接取自枚举与校验代码。</p><h2 id="支持的故障类型" tabindex="-1">支持的故障类型 <a class="header-anchor" href="#支持的故障类型" aria-label="Permalink to “支持的故障类型”">​</a></h2><table tabindex="0"><thead><tr><th>故障</th><th><code>FaultSpec</code> 变体</th><th>后端</th><th>参数</th><th>校验</th></tr></thead><tbody><tr><td>延迟</td><td><code>Latency</code></td><td><code>tc netem delay</code></td><td><code>milliseconds: u64</code></td><td><code>0 &lt; ms ≤ 86_400_000</code>(24 小时)</td></tr><tr><td>丢包</td><td><code>Loss</code></td><td><code>tc netem loss</code></td><td><code>percent: f64</code></td><td><code>0 &lt; percent ≤ 100</code></td></tr><tr><td>断连</td><td><code>Disconnect</code></td><td><code>iptables -t mangle</code> DROP</td><td><code>all_traffic: bool</code>(默认 <code>true</code>)</td><td>目标必须 IPv4</td></tr></tbody></table><p>CLI 选择:<code>--fault latency|loss|disconnect</code>。<code>latency</code> 必须带 <code>--milliseconds</code>,<code>loss</code> 必须带 <code>--percent</code>,<code>disconnect</code> 无参数。</p><h2 id="目标模型" tabindex="-1">目标模型 <a class="header-anchor" href="#目标模型" aria-label="Permalink to “目标模型”">​</a></h2><div class="language-rust" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">rust</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">pub</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> struct</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Target</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">    pub</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> source</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Option</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">IpNet</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;,</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">    pub</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> destination</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Option</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">IpNet</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;,</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">    pub</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> destination_port</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Option</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">u16</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><ul><li>CLI 暴露 <code>--destination &lt;CIDR&gt;</code>(必填)与 <code>--port-spec &lt;u16&gt;</code>(可选的目的端口匹配)。</li><li>目标必须是 <strong>IPv4</strong> —— 目标中任何 IPv6 网段都会被拒绝(core 报 <code>UnsupportedIpv6</code>,firewall 报 <code>TargetNotV4</code>)。</li><li>空目标(source 与 destination 均为空)会被拒绝,报 <code>EmptyTarget</code>。</li></ul><h2 id="安全约束" tabindex="-1">安全约束 <a class="header-anchor" href="#安全约束" aria-label="Permalink to “安全约束”">​</a></h2><p><code>inject</code> 请求到达 agent 后按顺序执行:</p><ol><li><strong>管理网段守卫</strong> —— 目标中的每个 CIDR 与 agent 的 <code>--management</code> 列表做重叠检查,重叠即拒绝(「管理流量绝不允许被注入故障」)。</li><li><strong>内在校验</strong>(<code>faultdeck_core::validate_injection</code>)—— 上表中的参数范围与仅 IPv4。</li><li><strong>单故障约束</strong> —— agent 只跟踪一个已生效故障;第二个 <code>inject</code> 返回 <code>another fault is already applied; rollback first</code>。</li><li><strong>载荷上限</strong> —— 请求行超过 64 KiB 拒绝。</li><li><strong>外部 qdisc preflight</strong> —— 若网卡根 qdisc 不是 FaultDeck 自己的 <code>100:</code> 句柄,适配器拒绝运行。</li></ol><h2 id="适配器生成的-tc-结构" tabindex="-1">适配器生成的 tc 结构 <a class="header-anchor" href="#适配器生成的-tc-结构" aria-label="Permalink to “适配器生成的 tc 结构”">​</a></h2><p>对 <code>latency</code>/<code>loss</code>,适配器构建 prio 层级,只对匹配波段注入故障:</p><div class="language-" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>tc qdisc add dev IFACE root handle 100: prio bands 3</span></span>
<span class="line"><span>tc filter add dev IFACE protocol ip parent 100: prio 1 u32 \\</span></span>
<span class="line"><span>   [match ip src …] [match ip dst …] [match ip dport PORT 0xffff] flowid 100:2</span></span>
<span class="line"><span>tc qdisc add dev IFACE parent 100:2 handle 50: netem delay 200ms   # 或: loss 30.000</span></span>
<span class="line"><span>tc qdisc add dev IFACE parent 100:3 fq_codel</span></span>
<span class="line"><span>tc filter add dev IFACE protocol ip parent 100: prio 2 u32 match u32 0 0 flowid 100:3</span></span></code></pre></div><ul><li>匹配的流量进入波段 <code>100:2</code> → netem;其余流量落到 <code>100:3</code>(fq_codel),不受影响。</li><li>百分比固定三位小数格式(<code>loss 30.000</code>)。</li><li>重新应用前会先删除上次遗留的 FaultDeck 根 qdisc。</li><li>应用过程中任一命令失败,适配器立即回滚根 qdisc。</li></ul><h2 id="disconnect" tabindex="-1">Disconnect <a class="header-anchor" href="#disconnect" aria-label="Permalink to “Disconnect”">​</a></h2><p><code>Disconnect</code> 没有 netem 等价物,因此 agent 将其交给防火墙模块:在 <strong>mangle</strong> 表创建 <code>FAULTDECK</code> 链并从 <code>INPUT</code> 跳转,对每个目标网段追加一条 <code>-d ADDR/PREFIX -j DROP</code> 规则。回滚时对链执行 flush(<code>-F</code>)与删除(<code>-X</code>)。<code>--iptables</code> 必须指向 iptables 二进制,否则 agent 返回 <code>iptables missing</code>。</p><h2 id="回滚" tabindex="-1">回滚 <a class="header-anchor" href="#回滚" aria-label="Permalink to “回滚”">​</a></h2><p><code>faultdeck remote rollback</code> 撤销当前生效的故障:</p><ul><li>netem 路径:删除根 qdisc;<code>tc</code> 的「Cannot find / No such device」类错误视为已清理(幂等)。</li><li>firewall 路径:flush 并删除 <code>FAULTDECK</code> 链。</li><li>当前无故障时,agent 应答 <code>nothing to roll back</code>。</li></ul><h2 id="dry-run-模式" tabindex="-1">Dry-run 模式 <a class="header-anchor" href="#dry-run-模式" aria-label="Permalink to “Dry-run 模式”">​</a></h2><p><code>NetemAdapter::dry_run(iface)</code>(库 API)只校验并返回将要执行的完整 <code>tc</code> 命令列表,不触碰系统 —— 测试在用,也适合在注入前检查命令。</p>`,22)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};